export const MYANMAR_TOWNSHIPS: MyanmarTownship[] = MYANMAR_REGIONS.flatMap((region) => region.cities);

export function getMyanmarTownshipLabel(cityId: string, lang: 'my' | 'en' = 'my'): string {
  const city = MYANMAR_TOWNSHIPS.find((item) => item.id === cityId);
  if (!city) return cityId;
  return lang === 'my'
    ? `${city.local} (${city.en}) • ${city.regionLocal}`
    : `${city.en}, ${city.regionEn}`;
}
